const email = $json;
const textOf = (value) => typeof value === 'string' ? value : (value?.text || '');
const sender = typeof email.from === 'string' ? email.from : (email.from?.value?.[0]?.address || email.from?.text || 'Sin remitente');
const subject = textOf(email.subject).trim() || '(Sin asunto)';
const plain = textOf(email.textPlain) || textOf(email.text);
const html = textOf(email.textHtml) || textOf(email.html);
const body = (plain || html.replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, '').replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')).trim();
if (!body && !Object.keys($input.item.binary || {}).length) throw new Error('Correo sin texto ni adjuntos: revisar manualmente esta ejecución.');
const headers = email.headers || email.metadata || {};
const messageId = String(email.messageId || headers['message-id'] || email.attributes?.uid || 'sin-id');
return { binary: $input.item.binary || {}, json: { remitente: String(sender), asunto: subject.slice(0,255), cuerpo: (body || 'Correo sin texto; revisar los adjuntos.').slice(0,16000), texto_recortado: body.length > 16000, fecha: String(email.date || new Date().toISOString()), message_id: messageId, demo: email.demo === true } };

let result = $json.output;
if (typeof result === 'string') { try { result = JSON.parse(result); } catch { throw new Error('La IA no devolvió JSON válido. No se creó un ticket.'); } }
if (!result || typeof result !== 'object') throw new Error('Falta la salida estructurada de IA.');
const categories = ['aplicaciones','infraestructura','accesos','otros'];
const priorities = { baja:1, normal:2, alta:3, urgente:4 };
for (const key of ['resumen','descripcion']) if (typeof result[key] !== 'string' || !result[key].trim()) throw new Error('Campo IA inválido: '+key);
if (!categories.includes(result.categoria) || !Object.hasOwn(priorities,result.prioridad)) throw new Error('Categoría o prioridad fuera del catálogo.');
if (!Array.isArray(result.datos_faltantes) || !result.datos_faltantes.every(v=>typeof v==='string') || typeof result.requiere_revision !== 'boolean') throw new Error('Salida IA incompleta.');
for (const key of ['project_id']) if (!Number.isSafeInteger(result[key]) || result[key] < 1) throw new Error('ID de proyecto/tipo inválido: '+key);
for (const key of ['assigned_to_id','membership_id','role_id']) if (!Number.isSafeInteger(result[key]) || result[key] < 0) throw new Error('ID de asignación inválido: '+key);
if (typeof result.motivo_asignacion !== 'string' || !result.motivo_asignacion.trim()) throw new Error('Falta motivo de asignación');
if (result.assigned_to_id > 0 && (!result.membership_id || !result.role_id)) throw new Error('Falta membresía o rol para validar la asignación');
if (!['Errores','Soporte'].includes(result.tipo_ticket)) throw new Error('Tipo de ticket fuera del catálogo permitido.');
const email = $('Normalizar correo').item.json;
// Correo real del remitente; nunca se toma de la respuesta de IA.
const sender = String(email.remitente || '').trim();
const addressMatch = sender.match(/<([^<>]+)>$/);
const requesterEmail = (addressMatch ? addressMatch[1] : sender).trim();
const validRequester = requesterEmail.length <= 254 && /^[^\s<>@,;]+@[^\s<>@,;]+\.[^\s<>@,;]+$/.test(requesterEmail);

// Escape content so email text cannot break the Markdown tables.
const cell = value => String(value ?? 'No disponible').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\|/g,'&#124;').replace(/[\r\n]+/g,' ').replace(/([\\x60*_\[\]])/g,'\$1');
const table = rows => ['| Campo | Detalle |','| --- | --- |', ...rows.map(([key,value])=>'| '+key+' | '+cell(value)+' |')].join('\n');
const lines = [
 '## Datos del correo', '', table([
 ['Remitente',email.remitente],['Asunto original',email.asunto],['Fecha',email.fecha],['Message-ID',email.message_id]
 ]), '', '## Análisis de la solicitud', '', result.descripcion.slice(0,6000), '',
 table([['Categoría sugerida',result.categoria],['Prioridad sugerida',result.prioridad],['Prioridad aplicada',result.requiere_revision?'normal':result.prioridad],['Requiere revisión',result.requiere_revision?'Sí':'No'],['Datos faltantes',result.datos_faltantes.slice(0,20).map(v=>v.slice(0,300)).join('; ')||'Ninguno identificado']]),
 '', '## Texto del correo'+(email.texto_recortado?' (recortado a 16000 caracteres)':''), '',
 String(email.cuerpo||'').split(/\r?\n/).map(line=>'> '+cell(line)).join('\n')
];
return { json: { routing: { tracker_name:result.tipo_ticket, category:result.categoria, user_id:result.assigned_to_id, membership_id:result.membership_id, role_id:result.role_id, reason:result.motivo_asignacion.slice(0,1500) }, issue: { custom_fields: validRequester ? [{ id: 1, value: requesterEmail }] : [], project_id:result.project_id,  subject: ((email.demo ? '[DEMO] ' : '') + (result.requiere_revision ? '[REVISAR] ' : '') + result.resumen.trim()).slice(0,255), description:lines.join('\n'), priority_id: result.requiere_revision ? 2 : priorities[result.prioridad] } } };

const original = $input.item;
const supported = new Set(['image/png', 'image/jpeg', 'image/webp', 'application/pdf']);
const maxFile = 4 * 1024 * 1024;
const maxTotal = 8 * 1024 * 1024;
const maxFiles = 4;
const selected = {};
const inventory = [];
let total = 0;
for (const [key, file] of Object.entries(original.binary || {})) {
  const mime = String(file.mimeType || 'application/octet-stream').toLowerCase();
  const entry = { archivo: file.fileName || key, tipo: mime, para_ia: false, motivo: 'Formato no seleccionado para IA; se adjunta a Redmine.' };
  if (supported.has(mime)) {
    try {
      const buffer = await this.helpers.getBinaryDataBuffer($itemIndex, key);
      if (buffer.length <= maxFile && total + buffer.length <= maxTotal && Object.keys(selected).length < maxFiles) {
        selected[key] = file;
        total += buffer.length;
        entry.para_ia = true;
        entry.motivo = 'Seleccionado para análisis visual/documental.';
      } else {
        entry.motivo = 'Supera los límites de análisis IA; se adjunta a Redmine.';
      }
    } catch {
      entry.motivo = 'No se pudo preparar para IA; se intentará adjuntar a Redmine.';
    }
  }
  inventory.push(entry);
}
return { json: { ...original.json, adjuntos: inventory }, binary: selected };

const original = $('Normalizar correo').item;
const selection = $('Seleccionar adjuntos para IA').item.json;
const issue = { ...$json.issue };
const inventory = selection.adjuntos || [];
const cell = value => String(value ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\|/g,'&#124;').replace(/[
]+/g,' ');
if (inventory.length) {
 issue.description += '

## Archivos del correo

| Archivo | Tipo | Tratamiento |
| --- | --- | --- |
' + inventory.map(a=>'| '+cell(a.archivo)+' | '+cell(a.tipo)+' | '+cell(a.motivo)+' |').join('
') + '

Los archivos se adjuntan al ticket. La selección para IA no garantiza su lectura; consultar el análisis anterior.';
}
return {json:{issue},binary:original.binary||{}};

const output = [];
for (const [group, item] of $input.all().entries()) {
  const files = Object.entries(item.binary || {});
  for (const [key, file] of files) {
    const name = String(file.fileName || key).replace(/[\\/\x00-\x1f]/g, '_').slice(0, 200) || 'adjunto';
    output.push({
      json: { group, expected: files.length, issue: item.json.issue, filename: name,
        content_type: file.mimeType || 'application/octet-stream' },
      binary: { data: file },
      pairedItem: { item: group },
    });
  }
}
return output;

const groups = new Map();
for (const [index, item] of $input.all().entries()) {
  const origin = $('Separar adjuntos').itemMatching(index).json;
  const token = item.json.upload?.token;
  if (typeof token !== 'string' || !token) throw new Error('Redmine no devolvió el token para ' + origin.filename);
  if (!groups.has(origin.group)) groups.set(origin.group, { issue: { ...origin.issue, uploads: [] }, expected: origin.expected, pairedItem: [] });
  const group = groups.get(origin.group);
  group.issue.uploads.push({ token, filename: origin.filename, content_type: origin.content_type });
  group.pairedItem.push({ item: index });
}
return Array.from(groups.values(), group => {
  if (group.issue.uploads.length !== group.expected) throw new Error('Faltan adjuntos: se detiene la creación del ticket.');
  return { json: { issue: group.issue }, pairedItem: group.pairedItem };
});

const proposal = $('Preparar ticket - Intaco').item.json;
const response = $json;
const project = response.body?.project;
if (response.statusCode !== 200 || !project || project.id !== proposal.issue.project_id || project.status !== 1) {
  throw new Error('El proyecto propuesto no existe, está inactivo o la credencial no puede consultarlo. No se creó el ticket.');
}
const issue = { ...proposal.issue };
const normalize = value => String(value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toLowerCase();
const requestedType = normalize(proposal.routing.tracker_name);
if (!['errores','soporte'].includes(requestedType)) {
  throw new Error('Tipo de ticket fuera del catálogo permitido. No se creó el ticket.');
}
const enabledTypes = (project.trackers || []).filter(t => normalize(t.name) === requestedType);
if (enabledTypes.length !== 1 || !Number.isSafeInteger(enabledTypes[0].id) || enabledTypes[0].id < 1) {
  throw new Error('El tipo solicitado no está habilitado o es ambiguo en el proyecto. No se creó el ticket.');
}
issue.tracker_id = enabledTypes[0].id;
const matches = (project.issue_categories || []).filter(category => normalize(category.name) === normalize(proposal.routing.category));
if (matches.length !== 1 || !Number.isSafeInteger(matches[0].id) || matches[0].id < 1) {
  throw new Error('La categoría "' + proposal.routing.category + '" no existe o es ambigua en el proyecto ' + project.id + '. Configurar sus categorías en Redmine. No se creó el ticket.');
}
issue.category_id = matches[0].id;
if (!proposal.routing.user_id) {
  delete issue.assigned_to_id;
  if (!issue.subject.includes('[REVISAR]')) issue.subject = ('[REVISAR] ' + issue.subject).slice(0, 255);
  issue.description += '\n\nASIGNACIÓN: sin responsable verificado; requiere revisión humana.';
}
return { json: { ...proposal, issue } };

const proposal = $('Validar proyecto y tipo').item.json;
const membershipResponse = $('Verificar membresía elegida').item.json;
const membership = membershipResponse.body?.membership;
const role = $json.body?.role;
const routing = proposal.routing;
const valid = membershipResponse.statusCode === 200 && $json.statusCode === 200 &&
  membership?.project?.id === proposal.issue.project_id &&
  membership?.user?.id === routing.user_id &&
  membership?.id === routing.membership_id &&
  membership.roles?.some(r => r.id === routing.role_id) &&
  role?.id === routing.role_id && role.assignable === true &&
  Array.isArray(role.permissions) && role.permissions.includes('view_issues');
const issue = { ...proposal.issue };
if (valid) {
  issue.assigned_to_id = routing.user_id;
  issue.description += '\n\nASIGNACIÓN VALIDADA\nResponsable: ' + membership.user.name +
    ' (ID ' + routing.user_id + ')\nRol: ' + role.name +
    '\nMotivo sugerido por IA: ' + routing.reason;
} else {
  delete issue.assigned_to_id;
  if (!issue.subject.includes('[REVISAR]')) issue.subject = ('[REVISAR] ' + issue.subject).slice(0, 255);
  issue.description += '\n\nASIGNACIÓN NO APLICADA: la membresía/rol propuestos no pudieron verificarse. Ticket sin responsable para revisión humana.';
}
return { json: { issue } };

let ml = { categoria:null, probabilidad:null, modelo_version:null, datos_entrenamiento:null, estado:'clasificacion_no_disponible' };
try { ml = { ...ml, ...$('Clasificar correo - Modelo 300').item.json.clasificacion_ml }; } catch { /* Optional comparison must not block the ticket. */ }
let output = $json.output;
if (typeof output === 'string') output = JSON.parse(output);
if (!output || typeof output !== 'object') throw new Error('Falta resultado del agente para comparar');
const analysis = { ...output };
const comparison = {
  categoria_ml: ml.categoria, categoria_llm: analysis.categoria,
  coinciden: ml.categoria ? ml.categoria === analysis.categoria : null,
  modelo_version: ml.modelo_version, datos_entrenamiento: ml.datos_entrenamiento,
  estado_ml: ml.estado,
  evaluacion_accuracy: false,
  nota: 'Comparación operativa, no evaluación de precisión: falta etiqueta humana y el agente puede utilizar adjuntos y herramientas.',
};
const labels = { accesos: 'Accesos', aplicaciones: 'Aplicaciones', infraestructura: 'Infraestructura', otros: 'Otros' };
analysis.descripcion = String(analysis.descripcion || '').slice(0,4800)
  + '\n\nClasificador Python (300 correos): ' + (labels[ml.categoria] || 'Sin clasificación');
return { json: { ...$json, output: analysis, comparacion_tecnicas: comparison } };

let result = $json.output;
if (typeof result === 'string') result = JSON.parse(result);
if (!result || !['crear_ticket','omitir'].includes(result.accion_correo) || typeof result.motivo_decision !== 'string' || !result.motivo_decision.trim()) throw new Error('No hay una decisión de correo válida. Revisar la ejecución; no se creó ticket.');
return {json:{...$json,output:result,crear_ticket:result.accion_correo==='crear_ticket'}};

